<template><div v-loading="loading"><el-button link @click="router.push('/basic/suppliers')">← {{t('suppliers.back')}}</el-button><div v-if="supplier" class="hero"><div><small>{{supplier.code}}</small><h2>{{displayName}}</h2><div><el-tag v-for="v in supplier.businessTypes" :key="v" effect="plain">{{optionLabel(v)}}</el-tag><el-tag :type="supplier.status==='ACTIVE'?'success':'info'">{{supplier.status==='ACTIVE'?t('common.active'):t('common.inactive')}}</el-tag></div></div><el-button v-if="auth.can('masterdata:supplier:write')" @click="editOpen=true">{{t('suppliers.editProfile')}}</el-button></div>
<el-card v-if="supplier" shadow="never"><el-tabs v-model="tab" @tab-change="loadTab"><el-tab-pane :label="t('suppliers.profile')" name="profile"><el-descriptions :column="2" border><el-descriptions-item :label="t('suppliers.nameZh')">{{supplier.nameZh||'—'}}</el-descriptions-item><el-descriptions-item :label="t('suppliers.nameEn')">{{supplier.nameEn||'—'}}</el-descriptions-item><el-descriptions-item :label="t('suppliers.country')">{{supplier.countryCode?countryName(supplier.countryCode,locale):'—'}}</el-descriptions-item><el-descriptions-item :label="t('suppliers.currency')">{{supplier.currency}}</el-descriptions-item><el-descriptions-item :label="t('suppliers.taxId')">{{supplier.taxId||'—'}}</el-descriptions-item><el-descriptions-item :label="t('suppliers.paymentTerm')">{{supplier.paymentTerm||'—'}}</el-descriptions-item><el-descriptions-item :label="t('suppliers.registeredAddress')" :span="2">{{supplier.registeredAddress||'—'}}</el-descriptions-item><el-descriptions-item :label="t('suppliers.address')" :span="2">{{supplier.address||'—'}}</el-descriptions-item><el-descriptions-item :label="t('suppliers.remark')" :span="2">{{supplier.remark||'—'}}</el-descriptions-item></el-descriptions></el-tab-pane>
<el-tab-pane :label="t('suppliers.contacts')" name="contacts"><section-head :title="t('suppliers.contacts')" :button="t('suppliers.addContact')" @add="openContact"/><el-table :data="contacts"><el-table-column :label="t('suppliers.name')" prop="name"/><el-table-column :label="t('suppliers.department')" prop="department"/><el-table-column :label="t('suppliers.phone')" prop="phone"/><el-table-column :label="t('suppliers.email')" prop="email"/><el-table-column :label="t('suppliers.primary')" width="90"><template #default="{row}"><el-tag v-if="row.isPrimary" type="success">{{t('suppliers.primary')}}</el-tag></template></el-table-column><el-table-column :label="t('common.actions')"><template #default="{row}"><el-button link type="danger" @click="removeContact(row)">{{t('common.deactivate')}}</el-button></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane :label="t('suppliers.factories')" name="factories"><el-table :data="factories"><el-table-column :label="t('suppliers.code')" width="140"><template #default="{row}"><el-button link type="primary" @click="router.push(`/basic/suppliers/factories/${row.id}`)">{{row.code}}</el-button></template></el-table-column><el-table-column :label="t('suppliers.factoryName')"><template #default="{row}">{{locale==='zh'?row.nameZh||row.nameEn:row.nameEn||row.nameZh}}</template></el-table-column><el-table-column :label="t('suppliers.country')" prop="countryCode"/><el-table-column :label="t('suppliers.city')" prop="city"/><el-table-column :label="t('common.status')" prop="status"/></el-table></el-tab-pane>
<el-tab-pane :label="t('suppliers.owners')" name="owners"><section-head :title="t('suppliers.owners')" :button="t('suppliers.addOwner')" @add="ownerOpen=true"/><el-table :data="owners"><el-table-column :label="t('suppliers.name')" prop="employeeName"/><el-table-column :label="t('suppliers.responsibility')" prop="responsibilityCode"/><el-table-column :label="t('suppliers.primary')"><template #default="{row}"><el-tag v-if="row.isPrimary" type="success">{{t('suppliers.primary')}}</el-tag></template></el-table-column><el-table-column :label="t('suppliers.period')"><template #default="{row}">{{row.startDate||'—'}} ~ {{row.endDate||'—'}}</template></el-table-column><el-table-column :label="t('common.actions')"><template #default="{row}"><el-button link type="danger" @click="removeOwner(row)">{{t('common.deactivate')}}</el-button></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane :label="t('suppliers.changes')" name="changes"><el-timeline><el-timeline-item v-for="c in changes" :key="c.id" :timestamp="formatTime(c.createdAt)"><strong>{{changeSummary(c)}}</strong><p>{{operatorName(c.operatorName)||'—'}} · {{changeSection(c.section)}}</p></el-timeline-item></el-timeline></el-tab-pane></el-tabs></el-card>

<el-dialog v-model="editOpen" :title="t('suppliers.editProfile')" width="650px"><el-form :model="edit" label-width="130px" class="form-grid"><el-form-item :label="t('suppliers.nameZh')"><el-input v-model="edit.nameZh"/></el-form-item><el-form-item :label="t('suppliers.nameEn')"><el-input v-model="edit.nameEn"/></el-form-item><el-form-item :label="t('suppliers.country')"><el-select v-model="edit.countryCode" filterable><el-option v-for="c in countryOptions(locale)" :key="c.code" :label="c.name" :value="c.code"/></el-select></el-form-item><el-form-item :label="t('suppliers.taxId')"><el-input v-model="edit.taxId"/></el-form-item><el-form-item :label="t('suppliers.businessType')" class="full"><el-checkbox-group v-model="edit.businessTypes"><el-checkbox v-for="o in businessOptions" :key="o.code" :value="o.code">{{optionLabel(o.code)}}</el-checkbox></el-checkbox-group></el-form-item><el-form-item :label="t('suppliers.paymentTerm')"><el-select v-model="edit.paymentTerm" filterable allow-create default-first-option clearable :placeholder="t('suppliers.paymentTermPlaceholder')"><el-option v-for="o in paymentOptions" :key="o.code" :label="o.label" :value="o.code"/></el-select></el-form-item><el-form-item :label="t('suppliers.registeredAddress')" class="full"><el-input v-model="edit.registeredAddress"/></el-form-item><el-form-item :label="t('suppliers.address')" class="full"><el-input v-model="edit.address"/></el-form-item><el-form-item :label="t('suppliers.remark')" class="full"><el-input v-model="edit.remark" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="editOpen=false">{{t('common.cancel')}}</el-button><el-button type="primary" @click="saveProfile">{{t('common.save')}}</el-button></template></el-dialog>
<el-dialog v-model="contactOpen" :title="t('suppliers.addContact')" width="520px"><el-form :model="contact" label-width="110px"><el-form-item :label="t('suppliers.name')" required><el-input v-model="contact.name"/></el-form-item><el-form-item :label="t('suppliers.department')"><el-input v-model="contact.department"/></el-form-item><el-form-item :label="t('suppliers.titleField')"><el-input v-model="contact.title"/></el-form-item><el-form-item :label="t('suppliers.phone')"><el-input v-model="contact.phone"/></el-form-item><el-form-item :label="t('suppliers.email')"><el-input v-model="contact.email"/></el-form-item><el-form-item><el-checkbox v-model="contact.isPrimary">{{t('suppliers.primary')}}</el-checkbox></el-form-item></el-form><template #footer><el-button @click="contactOpen=false">{{t('common.cancel')}}</el-button><el-button type="primary" @click="saveContact">{{t('common.save')}}</el-button></template></el-dialog>
<el-dialog v-model="ownerOpen" :title="t('suppliers.addOwner')" width="520px"><el-form :model="owner" label-width="120px"><el-form-item :label="t('suppliers.employee')" required><el-select v-model="owner.employeeId" filterable @change="employeeChanged"><el-option v-for="e in employees" :key="e.id" :label="`${e.employeeNo} · ${e.name}`" :value="e.id"/></el-select></el-form-item><el-form-item :label="t('suppliers.responsibility')"><el-select v-model="owner.responsibilityCode"><el-option v-for="o in ownerOptions" :key="o.code" :label="o.label" :value="o.code"/></el-select></el-form-item><el-form-item :label="t('suppliers.period')"><el-date-picker v-model="owner.dates" type="daterange" value-format="YYYY-MM-DD"/></el-form-item><el-form-item><el-checkbox v-model="owner.isPrimary">{{t('suppliers.primary')}}</el-checkbox></el-form-item></el-form><template #footer><el-button @click="ownerOpen=false">{{t('common.cancel')}}</el-button><el-button type="primary" @click="saveOwner">{{t('common.save')}}</el-button></template></el-dialog></div></template>
<script setup lang="ts">
import {computed,defineComponent,h,onMounted,reactive,ref} from 'vue';import {ElButton,ElMessage,ElMessageBox} from 'element-plus';import {useI18n} from 'vue-i18n';import {useRoute,useRouter} from 'vue-router';import {del,get,post,put} from '../api';import {countryName,countryOptions} from '../lib/countries';import {businessRoleLabel,changeSectionLabel,changeSummaryLabel,operatorDisplayName} from '../lib/masterDataDisplay';import {useAuthStore} from '../stores/auth'
const SectionHead=defineComponent({props:{title:String,button:String},emits:['add'],setup(p,{emit}){return()=>h('div',{class:'section-head'},[h('h3',p.title),h(ElButton,{type:'primary',onClick:()=>emit('add')},()=>p.button)])}})
const {t,locale}=useI18n(),route=useRoute(),router=useRouter(),auth=useAuthStore();const id=String(route.params.id),supplier=ref<any>(),loading=ref(false),tab=ref('profile'),editOpen=ref(false),contactOpen=ref(false),ownerOpen=ref(false),contacts=ref<any[]>([]),owners=ref<any[]>([]),factories=ref<any[]>([]),changes=ref<any[]>([]),employees=ref<any[]>([]),businessOptions=ref<any[]>([]),paymentOptions=ref<any[]>([]),ownerOptions=ref<any[]>([]);const edit=reactive<any>({}),contact=reactive({name:'',department:'',title:'',phone:'',email:'',isPrimary:false,remark:''}),owner=reactive<any>({employeeId:'',employeeName:'',responsibilityCode:'SALES',isPrimary:false,dates:[]});const displayName=computed(()=>locale.value==='zh'?supplier.value?.nameZh||supplier.value?.nameEn||supplier.value?.name:supplier.value?.nameEn||supplier.value?.nameZh||supplier.value?.name);function optionLabel(v:string){return businessRoleLabel(v,t,businessOptions.value.find(o=>o.code===v)?.label||v)}function changeSummary(c:any){return changeSummaryLabel(c,'supplier',t)}function changeSection(v:string){return changeSectionLabel(v,t)}function operatorName(v:string){return operatorDisplayName(v,t)}function formatTime(v:string){return v?new Date(v).toLocaleString():''}
async function load(){loading.value=true;try{const d=await get<any>(`/suppliers/${id}`);supplier.value=d.supplier;Object.assign(edit,d.supplier)}finally{loading.value=false}}async function loadTab(){if(tab.value==='contacts')contacts.value=(await get<any>(`/suppliers/${id}/contacts`)).contacts||[];if(tab.value==='owners')owners.value=(await get<any>(`/suppliers/${id}/owners`)).owners||[];if(tab.value==='factories')factories.value=(await get<any>('/factories',{supplier_id:id,page:1,page_size:200,status:'ALL'})).factories||[];if(tab.value==='changes')changes.value=(await get<any>(`/suppliers/${id}/changes`)).changes||[]}
async function saveProfile(){if(!String(edit.nameZh||'').trim()&&!String(edit.nameEn||'').trim()){ElMessage.warning(t('suppliers.nameRequired'));return}await put(`/suppliers/${id}`,{...edit,name:edit.nameZh||edit.nameEn,country:edit.countryCode});editOpen.value=false;ElMessage.success(t('suppliers.saved'));load()}function openContact(){Object.assign(contact,{name:'',department:'',title:'',phone:'',email:'',isPrimary:false,remark:''});contactOpen.value=true}async function saveContact(){await post(`/suppliers/${id}/contacts`,{contact});contactOpen.value=false;loadTab()}async function removeContact(r:any){await ElMessageBox.confirm(t('suppliers.confirmDeactivate'));await del(`/suppliers/${id}/contacts/${r.id}`);loadTab()}function employeeChanged(v:string){owner.employeeName=employees.value.find(e=>String(e.id)===String(v))?.name||''}async function saveOwner(){await post(`/suppliers/${id}/owners`,{owner:{employeeId:owner.employeeId,employeeName:owner.employeeName,responsibilityCode:owner.responsibilityCode,isPrimary:owner.isPrimary,startDate:owner.dates?.[0]||'',endDate:owner.dates?.[1]||''}});ownerOpen.value=false;loadTab()}async function removeOwner(r:any){await ElMessageBox.confirm(t('suppliers.confirmDeactivate'));await del(`/suppliers/${id}/owners/${r.id}`);loadTab()}
onMounted(async()=>{await load();const [e,b,p,o]=await Promise.all([get<any>('/employees',{page:1,page_size:200,status:'ACTIVE'}),get<any>('/options',{category:'SUPPLIER_BUSINESS_TYPE'}),get<any>('/options',{category:'PAYMENT_METHOD'}),get<any>('/options',{category:'SUPPLIER_OWNER_RESPONSIBILITY'})]);employees.value=e.employees||[];businessOptions.value=b.options||[];paymentOptions.value=p.options||[];ownerOptions.value=o.options||[]})
</script>
<style scoped>.hero{display:flex;justify-content:space-between;align-items:center;background:linear-gradient(120deg,#f2f8fa,#fff);border:1px solid #dce6eb;border-radius:16px;padding:22px 26px;margin:12px 0 18px}.hero h2{margin:4px 0 10px;color:#18324a}.hero .el-tag+.el-tag{margin-left:6px}.section-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.form-grid .full{grid-column:1/-1}.form-grid :deep(.el-select){width:100%}.el-timeline p{color:#82909b}@media(max-width:800px){.form-grid{grid-template-columns:1fr}.form-grid .full{grid-column:auto}}</style>
